71	// ─── Create ────────────────────────────────────────────────────────────────────
72	
73	export async function createProjectAction(
74	  formData: FormData
75	): Promise<ActionResult<{ id: string }>> {
76	  const auth = await getAuthenticatedUser()
77	  if (!auth) return { ok: false, error: 'Not authenticated' }
78	
79	  const role = auth.role as ReadRole
80	  // Receptionist can create projects per RLS
81	  if (role === 'guest_artist') return { ok: false, error: 'Insufficient permissions' }
82	
83	  const raw = {
84	    clientId: formData.get('clientId'),
85	    name: formData.get('name'),
86	    description: formData.get('description') || undefined,
87	    placement: formData.get('placement') || undefined,
88	    style: formData.get('style') || undefined,
89	    primaryArtistId: formData.get('primaryArtistId') || undefined,
90	    totalSessionsPlanned: formData.get('totalSessionsPlanned')
91	      ? Number(formData.get('totalSessionsPlanned'))
92	      : undefined,
93	    totalPriceCents: formData.get('totalPriceCents')
94	      ? Number(formData.get('totalPriceCents'))
95	      : 0,
96	    moodboardUrl: formData.get('moodboardUrl') || undefined,
97	    initialDepositCents: formData.get('initialDepositCents')
98	      ? Number(formData.get('initialDepositCents'))
99	      : undefined,
100	  }
101	
102	  const parsed = projectCreateSchema.safeParse(raw)
103	  if (!parsed.success) {
104	    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Validation failed' }
105	  }
106	
107	  // requestDeposit and bookingId are wizard-level flags not in the schema
108	  const requestDeposit = formData.get('requestDeposit') === 'true'
109	  const bookingIdRaw = formData.get('bookingId')
110	  const bookingId = typeof bookingIdRaw === 'string' && bookingIdRaw.length > 0
111	    ? bookingIdRaw
112	    : null
113	
114	  try {
115	    const project = await createProject(auth.studioId, parsed.data)
116	    revalidatePath('/projects')
117	
118	    // requestDeposit wiring — fire deposit reminder when a booking was created in same wizard flow
119	    if (requestDeposit) {
120	      if (bookingId) {
121	        const { sendDepositReminderAction } = await import('@/app/(app)/inbox/actions')
122	        const reminderResult = await sendDepositReminderAction(bookingId)
123	        if (!reminderResult.ok) {
124	          // Non-fatal — project created; log and continue
125	          logger.warn(
126	            { bookingId, projectId: project.id, error: reminderResult.error },
127	            'createProjectAction: deposit reminder send failed (non-fatal)',
128	          )
129	        } else {
130	          logger.info(
131	            { bookingId, projectId: project.id },
132	            'createProjectAction: deposit reminder sent',
133	          )
134	        }
135	      } else {
136	        // No booking yet — reminder deferred to first session booking
137	        logger.info(
138	          { projectId: project.id },
139	          'createProjectAction: requestDeposit=true but no bookingId — reminder deferred to first session booking',
140	        )
141	      }
142	    }
143	
144	    return { ok: true, data: { id: project.id } }
145	  } catch (err) {
146	    logger.error({ err }, 'createProjectAction failed')
147	    return { ok: false, error: 'Failed to create project' }
148	  }
149	}
