153	export async function updateProjectAction(
154	  id: string,
155	  formData: FormData
156	): Promise<ActionResult<void>> {
157	  const auth = await getAuthenticatedUser()
158	  if (!auth) return { ok: false, error: 'Not authenticated' }
159	  if (!canWrite(auth.role as ReadRole)) return { ok: false, error: 'Insufficient permissions' }
160	
161	  const raw = {
162	    name: formData.get('name') || undefined,
163	    description: formData.get('description') ?? undefined,
164	    placement: formData.get('placement') ?? undefined,
165	    style: formData.get('style') ?? undefined,
166	    primaryArtistId: formData.get('primaryArtistId') ?? undefined,
167	    totalSessionsPlanned: formData.get('totalSessionsPlanned')
168	      ? Number(formData.get('totalSessionsPlanned'))
169	      : undefined,
170	    totalPriceCents: formData.get('totalPriceCents')
171	      ? Number(formData.get('totalPriceCents'))
172	      : undefined,
173	    moodboardUrl: formData.get('moodboardUrl') ?? undefined,
174	    status: formData.get('status') ?? undefined,
175	  }
176	
177	  const parsed = projectUpdateSchema.safeParse(raw)
178	  if (!parsed.success) {
179	    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Validation failed' }
180	  }
181	
182	  try {
183	    await updateProject(auth.studioId, id, parsed.data)
184	    revalidatePath('/projects')
185	    revalidatePath(`/projects/${id}`)
186	    return { ok: true, data: undefined }
187	  } catch (err) {
188	    logger.error({ err, id }, 'updateProjectAction failed')
189	    return { ok: false, error: 'Failed to update project' }
190	  }
191	}
