273	export async function addReferenceAction(
274	  projectId: string,
275	  formData: FormData
276	): Promise<ActionResult<{ id: string }>> {
277	  const auth = await getAuthenticatedUser()
278	  if (!auth) return { ok: false, error: 'Not authenticated' }
279	  if (!canWrite(auth.role as ReadRole)) return { ok: false, error: 'Insufficient permissions' }
280	
281	  const supabase = await createClient()
282	
283	  const file = formData.get('file') as File | null
284	  if (!file) return { ok: false, error: 'No file provided' }
285	
286	  // Upload to Supabase Storage
287	  const fileExt = file.name.split('.').pop() ?? 'jpg'
288	  const storagePath = `${auth.studioId}/${projectId}/refs/${Date.now()}.${fileExt}`
289	
290	  const { error: uploadError } = await supabase.storage
291	    .from('project-references')
292	    .upload(storagePath, file, { upsert: false })
293	
294	  if (uploadError) {
295	    logger.error({ uploadError, projectId }, 'addReferenceAction upload failed')
296	    return { ok: false, error: 'Failed to upload image' }
297	  }
298	
299	  const raw = {
300	    storagePath,
301	    caption: (formData.get('caption') as string) || undefined,
302	    displayOrder: formData.get('displayOrder')
303	      ? Number(formData.get('displayOrder'))
304	      : undefined,
305	  }
306	
307	  const parsed = addReferenceSchema.safeParse(raw)
308	  if (!parsed.success) {
309	    return { ok: false, error: 'Validation failed' }
310	  }
311	
312	  try {
313	    const ref = await addProjectReference(auth.studioId, projectId, parsed.data)
314	    revalidatePath(`/projects/${projectId}`)
315	    return { ok: true, data: { id: ref.id } }
316	  } catch (err) {
317	    logger.error({ err, projectId }, 'addReferenceAction failed')
318	    return { ok: false, error: 'Failed to save reference' }
319	  }
320	}
