530	// ─── Deposit ledger (new table: project_deposit_transactions) ──────────────────
531	
532	const _depositTransactionSchema = z.object({
533	  amount_cents: z.number().int().positive().max(1_000_000_00, 'Amount exceeds the $1M cap'),
534	  method: z.enum(['stripe', 'cash', 'card', 'other']).optional(),
535	  note: z.string().max(500).optional(),
536	})
537	
538	async function _insertDepositTransaction(
539	  supabase: Awaited<ReturnType<typeof createClient>>,
540	  row: {
541	    project_id: string
542	    type: 'received' | 'applied' | 'refunded' | 'consumed'
543	    amount_cents: number
544	    method?: string | null
545	    note?: string | null
546	    applied_to_session_id?: string | null
547	    created_by: string
548	  }
549	): Promise<{ error: string | null }> {
550	  const { error } = await supabase
551	    .from('project_deposit_transactions' as 'projects')
552	    .insert(row as never)
553	  return { error: error?.message ?? null }
554	}
