557	  supabase: Awaited<ReturnType<typeof createClient>>,
558	  row: {
559	    project_id: string
560	    actor_id: string
561	    event_type: string
562	    details?: Record<string, unknown>
563	  }
564	): Promise<void> {
565	  const { error } = await supabase
566	    .from('project_activity_log' as 'projects')
