571	export async function recordDepositTransactionAction(
572	  projectId: string,
573	  input: { amount_cents: number; method?: string; note?: string }
574	): Promise<ActionResult<void>> {
575	  const auth = await getAuthenticatedUser()
576	  if (!auth) return { ok: false, error: 'Not authenticated' }
577	  if (!canAdmin(auth.role as ReadRole)) return { ok: false, error: 'Only owners and admins can record deposits' }
578	
579	  const parsed = _depositTransactionSchema.safeParse(input)
580	  if (!parsed.success) {
581	    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Validation failed' }
582	  }
583	
584	  const supabase = await createClient()
585	
586	  // W9 — explicit studio-scope guard before write
587	  const scopeCheck = await verifyProjectInStudio(supabase, auth.studioId, projectId)
588	  if (!scopeCheck.ok) return scopeCheck
589	
590	  const { error } = await _insertDepositTransaction(supabase, {
591	    project_id: projectId,
592	    type: 'received',
593	    amount_cents: parsed.data.amount_cents,
594	    method: parsed.data.method ?? null,
595	    note: parsed.data.note ?? null,
596	    created_by: auth.user.id,
597	  })
598	
599	  if (error) {
600	    logger.error({ error, projectId }, 'recordDepositTransactionAction failed')
601	    return { ok: false, error: 'Failed to record deposit' }
