// ─── Reference source detection ────────────────────────────────────────────────

type ReferenceSource = 'pinterest' | 'instagram' | 'behance' | 'upload' | 'url'

function detectUrlSource(url: string): ReferenceSource {
  try {
    const { hostname } = new URL(url)
    if (hostname.includes('pinterest.')) return 'pinterest'
    if (hostname.includes('instagram.')) return 'instagram'
    if (hostname.includes('behance.')) return 'behance'
  } catch {
    // malformed URL — fall through
  }
  return 'url'
}

// ─── Create ────────────────────────────────────────────────────────────────────

export async function createProjectAction(
  formData: FormData
): Promise<ActionResult<{ id: string; requestDepositPending: boolean }>> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { ok: false, error: 'Not authenticated' }

  const role = auth.role as ReadRole
  // Receptionist can create projects per RLS
  if (role === 'guest_artist') return { ok: false, error: 'Insufficient permissions' }

  // ── Parse JSON arrays sent from the client form ──────────────────────────────
  function parseJsonArray(raw: FormDataEntryValue | null): string[] {
    if (!raw || typeof raw !== 'string' || raw === '') return []
    try {
      const parsed = JSON.parse(raw) as unknown
      return Array.isArray(parsed) ? (parsed as string[]) : []
    } catch {
      return []
    }
  }

  const raw = {
    client_id: formData.get('client_id'),
    name: formData.get('name'),
    description: formData.get('description') || null,
    placement: formData.get('placement') || null,
    size: formData.get('size') || null,
    color_mode: formData.get('color_mode') || null,
    style_tags: parseJsonArray(formData.get('style_tags')),
    primary_artist_id: formData.get('primary_artist_id') || null,
    secondary_artist_ids: parseJsonArray(formData.get('secondary_artist_ids')),
    total_sessions_planned: formData.get('total_sessions_planned')
      ? Number(formData.get('total_sessions_planned'))
      : null,
    total_price_cents: formData.get('total_price_cents')
      ? Number(formData.get('total_price_cents'))
      : 0,
    initial_deposit_cents: formData.get('initial_deposit_cents')
      ? Number(formData.get('initial_deposit_cents'))
      : 0,
    deposit_apply_rule: formData.get('deposit_apply_rule') || 'last_session',
    reference_notes: formData.get('reference_notes') || null,
    request_deposit: formData.get('request_deposit') === 'true',
    request_deposit_channel:
      (formData.get('request_deposit_channel') as 'email' | 'sms') || 'email',
    moodboard_uploads: parseJsonArray(formData.get('moodboard_uploads')),
    moodboard_urls: parseJsonArray(formData.get('moodboard_urls')),
  }

  const parsed = createProjectSchema.safeParse(raw)
  if (!parsed.success) {
    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Validation failed' }
  }

  const input = parsed.data
  const supabase = await createClient()

  try {
    // 1. Insert the project row
    const { data: project, error: projectErr } = await supabase
      .from('projects')
      .insert({
        studio_id: auth.studioId,
        client_id: input.client_id,
        name: input.name,
        description: input.description ?? null,
        placement: input.placement ?? null,
        size: input.size ?? null,
        color_mode: input.color_mode ?? null,
        style_tags: input.style_tags,
        primary_artist_id: input.primary_artist_id ?? null,
        secondary_artist_ids: input.secondary_artist_ids,
        total_sessions_planned: input.total_sessions_planned ?? null,
        total_price_cents: input.total_price_cents,
        deposit_pool_cents: input.initial_deposit_cents,
        deposit_applied_cents: 0,
        deposit_apply_rule: input.deposit_apply_rule,
        reference_notes: input.reference_notes ?? null,
        status: 'planning' as const,
        started_at: new Date().toISOString(),
      })
      .select('id')
      .single()

    if (projectErr || !project) {
      logger.error({ err: projectErr, studioId: auth.studioId }, 'createProjectAction insert failed')
      return { ok: false, error: 'Failed to create project' }
    }

    const projectId = project.id

    // 2. Record initial deposit transaction if > 0
    if (input.initial_deposit_cents > 0) {
      const { error: depositErr } = await supabase.rpc(
        'record_project_deposit' as 'get_auth_user_id',
        {
          p_project_id: projectId,
          p_amount_cents: input.initial_deposit_cents,
          p_method: 'manual',
          p_note: 'Initial deposit recorded at project creation',
        } as never,
      )
      if (depositErr) {
        // Non-fatal — project created; log and continue
        logger.warn(
          { depositErr, projectId },
          'createProjectAction: record_project_deposit RPC failed (non-fatal)',
        )
      }
    }

    // 3. Insert moodboard upload references
    if (input.moodboard_uploads.length > 0) {
      const uploadRows = input.moodboard_uploads.map((storagePath, i) => ({
        project_id: projectId,
        storage_path: storagePath,
        source: 'upload',
        display_order: i,
        created_by: auth.user.id,
      }))
      const { error: uploadRefErr } = await supabase
        .from('project_references' as 'projects')
        .insert(uploadRows as never)
      if (uploadRefErr) {
        logger.warn({ uploadRefErr, projectId }, 'createProjectAction: upload reference insert failed (non-fatal)')
      }
    }

    // 4. Insert moodboard URL references
    if (input.moodboard_urls.length > 0) {
      const urlRows = input.moodboard_urls.map((url, i) => ({
        project_id: projectId,
        storage_path: '',
        source: detectUrlSource(url),
        external_url: url,
        thumbnail_url: null,
        display_order: (input.moodboard_uploads.length) + i,
        created_by: auth.user.id,
      }))
      const { error: urlRefErr } = await supabase
        .from('project_references' as 'projects')
        .insert(urlRows as never)
      if (urlRefErr) {
        logger.warn({ urlRefErr, projectId }, 'createProjectAction: url reference insert failed (non-fatal)')
      }
    }

    // 5. Log activity
    const { error: logErr } = await supabase
      .from('project_activity_log' as 'projects')
      .insert({
        project_id: projectId,
        actor_id: auth.user.id,
        event_type: 'created',
        details: {
          name: input.name,
          client_id: input.client_id,
          initial_deposit_cents: input.initial_deposit_cents,
        },
      } as never)
    if (logErr) logger.warn({ logErr, projectId }, 'createProjectAction: activity log failed (non-fatal)')

    revalidatePath('/projects')

    return {
      ok: true,
      data: { id: projectId, requestDepositPending: input.request_deposit },
    }
  } catch (err) {
    logger.error({ err }, 'createProjectAction failed')
    return { ok: false, error: 'Failed to create project' }
  }
}

