import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { NewProjectForm } from '@/components/projects/NewProjectForm'
import { Page } from '@/components/shared/Page'

export const metadata: Metadata = {
  title: 'New Project — InkOS',
}

export default async function NewProjectPage() {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  // Guest artists cannot create projects
  if (auth.role === 'guest_artist') redirect('/projects')

  const supabase = await createClient()

  const [artistsResult, clientsResult] = await Promise.all([
    supabase
      .from('artists')
      .select('id, display_name, avatar_url, sort_order')
      .eq('studio_id', auth.studioId)
      .eq('status', 'active')
      .order('sort_order'),
    supabase
      .from('clients')
      .select('id, first_name, last_name, email, phone')
      .eq('studio_id', auth.studioId)
      .is('archived_at', null)
      .order('first_name')
      .limit(200),
  ])

  return (
    <Page
      title="New project"
      subtitle="Group multi-session tattoos — sleeves, back pieces, bodysuits — into a single project."
      backAction={{ href: '/projects' }}
      narrowWidth={720}
    >
      <NewProjectForm
        artists={artistsResult.data ?? []}
        clients={clientsResult.data ?? []}
      />
    </Page>
  )
}

