  clients: Client[]
}

// ─── Time-ago helper ──────────────────────────────────────────────────────────

function formatTimeAgo(ms: number): string {
  const rtf = new Intl.RelativeTimeFormat('en', { numeric: 'auto' })
  const diffS = Math.round((Date.now() - ms) / 1000)
  if (diffS < 60) return rtf.format(-diffS, 'second')
  const diffM = Math.round(diffS / 60)
  if (diffM < 60) return rtf.format(-diffM, 'minute')
  const diffH = Math.round(diffM / 60)
  return rtf.format(-diffH, 'hour')
}

// ─── Segmented control ────────────────────────────────────────────────────────

interface SegmentedOption<T extends string> {
  value: T
  label: string
}

function SegmentedControl<T extends string>({
  options,
  value,
  onChange,
}: {
  options: SegmentedOption<T>[]
  value: T
  onChange: (v: T) => void
}) {
  return (
    <div className="inline-flex rounded-lg border border-[var(--color-border)] overflow-hidden">
      {options.map((opt) => (
        <button
          key={opt.value}
          type="button"
          onClick={() => onChange(opt.value)}
          className={[
            'px-3 py-1.5 text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-rust)]',
            opt.value === value
              ? 'bg-[var(--color-onyx)] text-[var(--color-bone)]'
              : 'bg-transparent text-[var(--color-stone)] hover:text-[var(--color-onyx)] hover:bg-[var(--color-stone)]/10',
          ].join(' ')}
        >
          {opt.label}
        </button>
      ))}
    </div>
  )
}

// ─── Component ────────────────────────────────────────────────────────────────

export function NewProjectForm({ artists, clients }: NewProjectFormProps) {
  const router = useRouter()
  const [isPending, startTransition] = useTransition()
  const [errors, setErrors] = useState<Record<string, string>>({})
  const autosaveTimerRef = useRef<ReturnType<typeof setInterval> | null>(null)
  const lastSavedRef = useRef<number | null>(null)
  const [lastSaved, setLastSaved] = useState<number | null>(null)
  const [draftBanner, setDraftBanner] = useState<string | null>(null)
  const [quickAddOpen, setQuickAddOpen] = useState(false)

  // ── Section 1 ──────────────────────────────────────────────────────────────
  const [clientId, setClientId] = useState<string | null>(null)
  const [name, setName] = useState('')
  const [description, setDescription] = useState('')
  const [placement, setPlacement] = useState('')
  const [size, setSize] = useState<ProjectSizeValue | null>(null)
  const [colorMode, setColorMode] = useState<ColorModeValue>('color')

  // ── Section 2 ──────────────────────────────────────────────────────────────
  const [styleTags, setStyleTags] = useState<ProjectStyle[]>([])
  const [primaryArtistId, setPrimaryArtistId] = useState<string | null>(null)
  const [secondaryArtistIds, setSecondaryArtistIds] = useState<string[]>([])
  const [totalSessionsPlanned, setTotalSessionsPlanned] = useState('')
  const [totalPriceCents, setTotalPriceCents] = useState(0)
  const [initialDepositCents, setInitialDepositCents] = useState(0)
  const [depositApplyRule, setDepositApplyRule] = useState<DepositApplyRuleValue>('last_session')
  const [requestDeposit, setRequestDeposit] = useState(false)
  const [requestDepositChannel, setRequestDepositChannel] = useState<'email' | 'sms'>('email')
  const [moodboardTab, setMoodboardTab] = useState('upload')
  const [pendingUploads, setPendingUploads] = useState<PendingUpload[]>([])
  const [moodboardUrls, setMoodboardUrls] = useState('')
  const [referenceNotes, setReferenceNotes] = useState('')

  // ── Computed ───────────────────────────────────────────────────────────────
  const sessions = totalSessionsPlanned ? parseInt(totalSessionsPlanned, 10) : 0
  const perSession =
    sessions > 0 && totalPriceCents > 0 ? Math.round(totalPriceCents / sessions) : null

  // ── Draft ──────────────────────────────────────────────────────────────────

  const buildDraft = useCallback((): DraftState => ({
    clientId,
    name,
    description,
    placement,
    size,
    colorMode,
    styleTags,
    primaryArtistId,
    secondaryArtistIds,
    totalSessionsPlanned,
    totalPriceCents,
    initialDepositCents,
    depositApplyRule,
    requestDeposit,
    requestDepositChannel,
    moodboardUrls,
    referenceNotes,
    savedAt: Date.now(),
  }), [
    clientId, name, description, placement, size, colorMode, styleTags,
    primaryArtistId, secondaryArtistIds, totalSessionsPlanned, totalPriceCents,
    initialDepositCents, depositApplyRule, requestDeposit, requestDepositChannel,
    moodboardUrls, referenceNotes,
  ])

  const saveDraft = useCallback(() => {
    try {
      localStorage.setItem(DRAFT_KEY, JSON.stringify(buildDraft()))
      lastSavedRef.current = Date.now()
      setLastSaved(Date.now())
    } catch {
      // localStorage unavailable — silent
    }
  }, [buildDraft])

  const clearDraft = useCallback(() => {
    try { localStorage.removeItem(DRAFT_KEY) } catch { /* no-op */ }
  }, [])

  // Restore draft on mount
  useEffect(() => {
    try {
      const raw = localStorage.getItem(DRAFT_KEY)
      if (!raw) return
      const draft = JSON.parse(raw) as DraftState
      if (Date.now() - draft.savedAt > DRAFT_TTL_MS) {
        clearDraft()
        return
      }
      setClientId(draft.clientId)
      setName(draft.name)
      setDescription(draft.description)
      setPlacement(draft.placement)
      setSize(draft.size)
      setColorMode(draft.colorMode ?? 'color')
      setStyleTags(draft.styleTags ?? [])
      setPrimaryArtistId(draft.primaryArtistId)
      setSecondaryArtistIds(draft.secondaryArtistIds ?? [])
      setTotalSessionsPlanned(draft.totalSessionsPlanned)
      setTotalPriceCents(draft.totalPriceCents)
      setInitialDepositCents(draft.initialDepositCents)
      setDepositApplyRule(draft.depositApplyRule ?? 'last_session')
      setRequestDeposit(draft.requestDeposit ?? false)
      setRequestDepositChannel(draft.requestDepositChannel ?? 'email')
      setMoodboardUrls(draft.moodboardUrls ?? '')
      setReferenceNotes(draft.referenceNotes ?? '')
      setDraftBanner(formatTimeAgo(draft.savedAt))
    } catch { /* corrupt draft — ignore */ }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // Start autosave interval after mount
  useEffect(() => {
    autosaveTimerRef.current = setInterval(saveDraft, AUTOSAVE_INTERVAL_MS)
    return () => {
      if (autosaveTimerRef.current) clearInterval(autosaveTimerRef.current)
    }
  }, [saveDraft])

  // ── Options ────────────────────────────────────────────────────────────────

  const clientOptions: ComboBoxOption[] = useMemo(() => {
    const opts: ComboBoxOption[] = clients.map((c) => {
      const label = `${c.first_name}${c.last_name ? ` ${c.last_name}` : ''}`
      const description = c.email ?? c.phone ?? undefined
      return { value: c.id, label, description }
    })
    return opts
  }, [clients])

  const placementOptions: ComboBoxOption[] = useMemo(() =>
    PLACEMENT_PRESETS.map((p) => ({ value: p, label: p })),
    [],
  )

  const primaryArtistOptions: ComboBoxOption[] = useMemo(() =>
    artists.map((a) => ({ value: a.id, label: a.display_name })),
    [artists],
  )

  const secondaryArtistOptions: ComboBoxOption[] = useMemo(() =>
    artists
      .filter((a) => a.id !== primaryArtistId)
      .map((a) => ({ value: a.id, label: a.display_name })),
    [artists, primaryArtistId],
  )

  // ── Style tag toggle ────────────────────────────────────────────────────────

  const toggleStyleTag = (tag: ProjectStyle) => {
    setStyleTags((prev) =>
      prev.includes(tag)
        ? prev.filter((t) => t !== tag)
        : prev.length < 10 ? [...prev, tag] : prev
    )
  }

  // ── Secondary artist toggle ─────────────────────────────────────────────────

  const toggleSecondaryArtist = (id: string) => {
    setSecondaryArtistIds((prev) =>
      prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]
    )
  }

  // ── File upload ─────────────────────────────────────────────────────────────

  const handleFilesAccepted = useCallback((files: File[]) => {
    const current = pendingUploads.length
    const allowed = MAX_UPLOAD_FILES - current
    if (allowed <= 0) {
      toast.error(`Maximum ${MAX_UPLOAD_FILES} images allowed.`)
      return
    }
    const toAdd = files.slice(0, allowed)
    const newUploads: PendingUpload[] = toAdd.map((file) => ({
      id: `${Date.now()}-${Math.random().toString(36).slice(2)}`,
      file,
      previewUrl: URL.createObjectURL(file),
      storagePath: null,
      uploading: false,
      error: null,
    }))
    setPendingUploads((prev) => [...prev, ...newUploads])
  }, [pendingUploads.length])

  const removeUpload = (id: string) => {
    setPendingUploads((prev) => {
      const target = prev.find((u) => u.id === id)
      if (target) URL.revokeObjectURL(target.previewUrl)
      return prev.filter((u) => u.id !== id)
    })
  }

  // Cleanup object URLs on unmount
  useEffect(() => {
    return () => {
      pendingUploads.forEach((u) => URL.revokeObjectURL(u.previewUrl))
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // ── Upload files to Supabase storage before submit ──────────────────────────

  const uploadFilesToStorage = async (): Promise<string[]> => {
    if (pendingUploads.length === 0) return []

    const uploadedPaths: string[] = []

    for (const upload of pendingUploads) {
      const fd = new FormData()
      fd.set('file', upload.file)

      try {
        const res = await fetch('/api/projects/upload-reference', {
          method: 'POST',
          body: fd,
        })
        if (res.ok) {
          const json = await res.json() as { storage_path: string }
          uploadedPaths.push(json.storage_path)
        } else {
          logger.warn('Reference upload failed for file:', upload.file.name)
        }
      } catch {
        // Non-fatal: image skipped on error
      }
    }

    return uploadedPaths
  }

  // ── Parse moodboard URLs ────────────────────────────────────────────────────

  const parsedMoodboardUrls = useMemo(() => {
    return moodboardUrls
      .split('\n')
      .map((l) => l.trim())
      .filter((l) => {
        try { new URL(l); return true } catch { return false }
      })
  }, [moodboardUrls])

  // ── Submit ──────────────────────────────────────────────────────────────────

  const submit = async (navigateTo: 'project' | 'calendar') => {
    setErrors({})

    if (!clientId) {
      setErrors({ clientId: 'Client is required' })
      return
    }
    if (!name.trim()) {
      setErrors({ name: 'Project name is required' })
      return
    }

    startTransition(async () => {
      // Upload pending files first (non-blocking for project creation)
      let uploadedPaths: string[] = []
      try {
        uploadedPaths = await uploadFilesToStorage()
      } catch {
        // Continue without uploads
      }

      const fd = new FormData()
      fd.set('client_id', clientId)
      fd.set('name', name.trim())
      if (description) fd.set('description', description)
      if (placement) fd.set('placement', placement)
      if (size) fd.set('size', size)
      if (colorMode) fd.set('color_mode', colorMode)
      fd.set('style_tags', JSON.stringify(styleTags))
      if (primaryArtistId) fd.set('primary_artist_id', primaryArtistId)
      fd.set('secondary_artist_ids', JSON.stringify(secondaryArtistIds))
      if (totalSessionsPlanned) fd.set('total_sessions_planned', totalSessionsPlanned)
      fd.set('total_price_cents', String(totalPriceCents))
      fd.set('initial_deposit_cents', String(initialDepositCents))
      fd.set('deposit_apply_rule', depositApplyRule)
      if (referenceNotes) fd.set('reference_notes', referenceNotes)
      fd.set('request_deposit', String(requestDeposit && initialDepositCents === 0))
      fd.set('request_deposit_channel', requestDepositChannel)
      fd.set('moodboard_uploads', JSON.stringify(uploadedPaths))
      fd.set('moodboard_urls', JSON.stringify(parsedMoodboardUrls))

      const result = await createProjectAction(fd)

      if (!result.ok) {
        toast.error(result.error)
        return
      }

      clearDraft()
      toast.success('Project created')

      if (navigateTo === 'calendar') {
        const params = new URLSearchParams()
        params.set('new_booking_project', result.data.id)
        if (primaryArtistId) params.set('new_booking_artist', primaryArtistId)
        router.push(`/calendar?${params.toString()}`)
      } else {
        router.push(`/projects/${result.data.id}`)
      }
    })
  }

  const handleSubmitProject = () => { void submit('project') }
  const handleSubmitCalendar = () => { void submit('calendar') }

  // ── Form keyboard shortcut ──────────────────────────────────────────────────
  // Default Enter submits the primary action (Create & book first session)
  const handleFormKeyDown = (e: React.KeyboardEvent<HTMLFormElement>) => {
    if (e.key === 'Enter' && !e.shiftKey && e.target instanceof HTMLInputElement) {
      e.preventDefault()
      handleSubmitCalendar()
    }
  }

  // ── Color mode options ──────────────────────────────────────────────────────
  const colorModeOptions = COLOR_MODE_VALUES.map((v) => ({
    value: v,
    label: COLOR_MODE_LABELS[v],
  }))

  const depositRuleOptions = DEPOSIT_APPLY_RULE_VALUES.map((v) => ({
    value: v,
    label: DEPOSIT_APPLY_RULE_LABELS[v],
  }))

  // ─────────────────────────────────────────────────────────────────────────────

  return (
    <>
      <QuickAddClientModal
        open={quickAddOpen}
        onOpenChange={(open) => {
          setQuickAddOpen(open)
        }}
      />

      {/* Draft restored banner */}
      {draftBanner && (
        <div className="mb-4 flex items-center justify-between rounded-lg border border-[var(--color-border)] bg-[var(--color-bone)] px-4 py-2.5 text-sm text-[var(--color-stone)]">
          <span>Draft restored — {draftBanner}</span>
          <button
            type="button"
            onClick={() => { clearDraft(); setDraftBanner(null) }}
            className="ml-3 rounded-sm p-0.5 opacity-60 hover:opacity-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-rust)]"
            aria-label="Dismiss draft"
          >
            <X className="size-4" aria-hidden="true" />
          </button>
        </div>
      )}

      <form
        onKeyDown={handleFormKeyDown}
        className="space-y-4"
        onSubmit={(e) => { e.preventDefault() }}
      >
        {/* ── Section 1: Client & Basics ──────────────────────────────────────── */}
        <Card className="shadow-[var(--shadow-card)]">
          <CardHeader className="pb-3">
            <CardTitle className="text-base">Client &amp; Basics</CardTitle>
            <CardDescription className="text-sm">Who is this project for?</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {/* Client */}
            <div className="space-y-1.5">
              <Label htmlFor="client-combobox">
                Client <span className="text-destructive" aria-hidden="true">*</span>
              </Label>
              <ComboBox
                options={clientOptions}
                value={clientId}
                onValueChange={setClientId}
                placeholder="Search clients…"
                searchPlaceholder="Type name or email…"
              />
              {/* Create new client action */}
              <button
                type="button"
                onClick={() => setQuickAddOpen(true)}
                className="text-xs text-[var(--color-stone)] hover:text-[var(--color-onyx)] underline-offset-2 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-rust)] rounded-sm"
              >
                + Create new client
              </button>
              {errors.clientId && (
                <p role="alert" className="text-xs text-destructive">{errors.clientId}</p>
              )}
            </div>

            {/* Project name */}
            <div className="space-y-1.5">
              <Label htmlFor="project-name">
                Project name <span className="text-destructive" aria-hidden="true">*</span>
              </Label>
              <Input
                id="project-name"
                placeholder="e.g. Dragon Sleeve"
                value={name}
                onChange={(e) => setName(e.target.value)}
                maxLength={120}
              />
              <p className="text-xs text-[var(--color-stone)]">
                Short name you&apos;ll see often. Client can see this too.
              </p>
              {errors.name && (
                <p role="alert" className="text-xs text-destructive">{errors.name}</p>
              )}
            </div>

            {/* Placement */}
            <div className="space-y-1.5">
              <Label>Placement</Label>
              <ComboBox
                options={placementOptions}
                value={placement || null}
                onValueChange={(v) => setPlacement(v ?? '')}
                placeholder="Select or type placement…"
                searchPlaceholder="Forearm, back, etc…"
              />
            </div>

            {/* Size */}
            <div className="space-y-1.5">
              <Label htmlFor="project-size">Size</Label>
              <Select
                value={size ?? ''}
                onValueChange={(v) => setSize(v as ProjectSizeValue || null)}
              >
                <SelectTrigger id="project-size">
                  <SelectValue placeholder="Select size…" />
                </SelectTrigger>
                <SelectContent>
                  {PROJECT_SIZE_VALUES.map((s) => (
                    <SelectItem key={s} value={s}>
                      {SIZE_LABELS[s]}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Color / B&G */}
            <div className="space-y-1.5">
              <Label>Color / B&amp;G</Label>
              <div>
                <SegmentedControl<ColorModeValue>
                  options={colorModeOptions}
                  value={colorMode}
                  onChange={setColorMode}
                />
              </div>
            </div>

            {/* Description */}
            <div className="space-y-1.5">
              <Label htmlFor="project-description">Description</Label>
              <Textarea
                id="project-description"
                placeholder="Brief description of the project…"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                rows={3}
                maxLength={2000}
                className="resize-none"
              />
            </div>
          </CardContent>
        </Card>

        {/* ── Section 2: Style & Deposit Plan ─────────────────────────────────── */}
        <Card className="shadow-[var(--shadow-card)]">
          <CardHeader className="pb-3">
            <CardTitle className="text-base">Style &amp; Deposit Plan</CardTitle>
            <CardDescription className="text-sm">
              Optional details for planning and deposit tracking.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-5">
            {/* Style tags */}
            <div className="space-y-2">
              <Label>Style</Label>
              <div className="flex flex-wrap gap-2" role="group" aria-label="Style tags">
                {PROJECT_STYLES.map((s) => (
                  <button
                    key={s}
                    type="button"
                    onClick={() => toggleStyleTag(s)}
                    aria-pressed={styleTags.includes(s)}
                    className={[
                      'rounded-full border px-3 py-1 text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-rust)]',
                      styleTags.includes(s)
                        ? 'border-[var(--color-onyx)] bg-[var(--color-onyx)] text-[var(--color-bone)]'
                        : 'border-[var(--color-border)] bg-transparent text-[var(--color-stone)] hover:border-[var(--color-onyx)] hover:text-[var(--color-onyx)]',
                    ].join(' ')}
                  >
                    {STYLE_LABELS[s]}
                  </button>
                ))}
              </div>
              {styleTags.length === 10 && (
                <p className="text-xs text-[var(--color-stone)]">Maximum 10 tags selected.</p>
              )}
            </div>

            {/* Primary artist */}
            <div className="space-y-1.5">
              <Label>Primary Artist</Label>
              <ComboBox
                options={primaryArtistOptions}
                value={primaryArtistId}
                onValueChange={(v) => {
                  setPrimaryArtistId(v)
                  // Remove from secondary if now primary
                  setSecondaryArtistIds((prev) => prev.filter((id) => id !== v))
                }}
                placeholder="Assign artist…"
                searchPlaceholder="Search artists…"
              />
            </div>

            {/* Secondary artists */}
            {artists.length > 1 && (
              <div className="space-y-2">
                <Label>Secondary Artists</Label>
                {secondaryArtistOptions.length === 0 ? (
                  <p className="text-xs text-[var(--color-stone)]">
                    No other active artists available.
                  </p>
                ) : (
                  <div className="flex flex-wrap gap-2" role="group" aria-label="Secondary artists">
                    {secondaryArtistOptions.map((a) => (
                      <button
                        key={a.value}
                        type="button"
                        onClick={() => toggleSecondaryArtist(a.value)}
                        aria-pressed={secondaryArtistIds.includes(a.value)}
                        className={[
                          'rounded-full border px-3 py-1 text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-rust)]',
                          secondaryArtistIds.includes(a.value)
                            ? 'border-[var(--color-onyx)] bg-[var(--color-onyx)] text-[var(--color-bone)]'
                            : 'border-[var(--color-border)] bg-transparent text-[var(--color-stone)] hover:border-[var(--color-onyx)] hover:text-[var(--color-onyx)]',
                        ].join(' ')}
                      >
                        {a.label}
                      </button>
                    ))}
                  </div>
                )}
              </div>
            )}

            {/* Total sessions */}
            <div className="space-y-1.5">
              <Label htmlFor="sessions-planned">Total sessions</Label>
              <Input
                id="sessions-planned"
                type="number"
                placeholder="Leave blank for open-ended"
                value={totalSessionsPlanned}
                onChange={(e) => setTotalSessionsPlanned(e.target.value)}
                min={1}
                max={100}
              />
            </div>

            {/* Total price */}
            <div className="space-y-1.5">
              <Label>Total price</Label>
              <MoneyInput
                value={totalPriceCents}
                onValueChange={(v) => setTotalPriceCents(v ?? 0)}
                placeholder="0.00"
              />
              {perSession !== null && (
                <p className="text-xs text-[var(--color-stone)] font-variant-numeric tabular-nums">
                  {`≈ ${formatCurrency(perSession)}/session`}
                </p>
              )}
            </div>

            {/* Initial deposit */}
            <div className="space-y-1.5">
              <Label>Initial deposit</Label>
              <MoneyInput
                value={initialDepositCents}
                onValueChange={(v) => setInitialDepositCents(v ?? 0)}
                placeholder="0.00"
              />
              <p className="text-xs text-[var(--color-stone)]">
                Records a deposit already received into the project pool.
              </p>
            </div>

            {/* Deposit apply rule */}
            <div className="space-y-1.5">
              <Label>Deposit apply rule</Label>
              <div>
                <SegmentedControl<DepositApplyRuleValue>
                  options={depositRuleOptions}
                  value={depositApplyRule}
                  onChange={setDepositApplyRule}
                />
              </div>
            </div>

            {/* Request deposit from client (only when no deposit recorded) */}
            {initialDepositCents === 0 && (
              <div className="rounded-lg border border-[var(--color-border)] p-4 space-y-3">
                <div className="flex items-center justify-between gap-3">
                  <div>
                    <p className="text-sm font-medium text-[var(--color-onyx)]">
                      Request deposit from client
                    </p>
                    <p className="text-xs text-[var(--color-stone)] mt-0.5">
                      Sprint 5 will send a Dodo payment link.
                    </p>
                  </div>
                  <Switch
                    checked={requestDeposit}
                    onCheckedChange={setRequestDeposit}
                    aria-label="Request deposit from client"
                  />
                </div>
                {requestDeposit && (
                  <div className="space-y-1.5 pt-1">
                    <Label className="text-xs">Send via</Label>
                    <SegmentedControl<'email' | 'sms'>
                      options={[
                        { value: 'email', label: 'Email' },
                        { value: 'sms', label: 'SMS' },
                      ]}
                      value={requestDepositChannel}
                      onChange={setRequestDepositChannel}
                    />
                  </div>
                )}
              </div>
            )}

            {/* Moodboard */}
            <div className="space-y-2">
              <Label>Moodboard</Label>
              <Tabs value={moodboardTab} onValueChange={setMoodboardTab}>
                <TabsList className="w-full justify-start">
                  <TabsTrigger value="upload" className="gap-2">
                    <Upload className="size-3.5" aria-hidden="true" />
                    Upload images
                  </TabsTrigger>
                  <TabsTrigger value="url" className="gap-2">
                    <Link2 className="size-3.5" aria-hidden="true" />
                    Paste URL
                  </TabsTrigger>
                  <TabsTrigger value="flash" disabled className="gap-2 opacity-40">
                    <ImageOff className="size-3.5" aria-hidden="true" />
                    Flash designs
                  </TabsTrigger>
                </TabsList>

                <TabsContent value="upload" className="mt-3">
                  <FileDropzone
                    accept={{
                      'image/jpeg': ['.jpg', '.jpeg'],
                      'image/png': ['.png'],
                      'image/webp': ['.webp'],
                      'image/heic': ['.heic'],
                    }}
                    maxSize={MAX_UPLOAD_BYTES}
                    maxFiles={MAX_UPLOAD_FILES - pendingUploads.length}
                    onFilesAccepted={handleFilesAccepted}
                    onFilesRejected={(rejections) => {
                      const first = rejections[0]
                      if (first) toast.error(`${first.file.name}: ${first.errors[0] ?? 'File rejected'}`)
                    }}
                  />
                  {pendingUploads.length > 0 && (
                    <div className="mt-3 grid grid-cols-4 gap-2">
                      {pendingUploads.map((u) => (
                        <div key={u.id} className="relative group rounded-md overflow-hidden aspect-square bg-[var(--color-stone)]/10">
                          {/* eslint-disable-next-line @next/next/no-img-element */}
                          <img
                            src={u.previewUrl}
                            alt={u.file.name}
                            className="w-full h-full object-cover"
                          />
                          <button
                            type="button"
                            onClick={() => removeUpload(u.id)}
                            className="absolute top-1 right-1 rounded-full bg-[var(--color-onyx)]/70 p-0.5 opacity-0 group-hover:opacity-100 transition-opacity focus-visible:opacity-100 focus-visible:outline-none"
                            aria-label={`Remove ${u.file.name}`}
                          >
                            <X className="size-3 text-[var(--color-bone)]" aria-hidden="true" />
                          </button>
                        </div>
                      ))}
                    </div>
                  )}
                  <p className="mt-2 text-xs text-[var(--color-stone)]">
                    JPEG / PNG / WebP / HEIC · Max {MAX_UPLOAD_FILES} images · 10 MB each
                  </p>
                </TabsContent>

                <TabsContent value="url" className="mt-3 space-y-2">
                  <Textarea
                    placeholder={`https://pinterest.com/pin/…\nhttps://instagram.com/p/…\nhttps://behance.net/gallery/…`}
                    value={moodboardUrls}
                    onChange={(e) => setMoodboardUrls(e.target.value)}
                    rows={4}
                    className="resize-none font-mono text-xs"
                  />
                  <p className="text-xs text-[var(--color-stone)]">
                    One URL per line. Pinterest, Instagram, and Behance links are recognised automatically.
                  </p>
                  {parsedMoodboardUrls.length > 0 && (
                    <p className="text-xs text-[var(--color-stone)]">
                      {parsedMoodboardUrls.length} valid URL{parsedMoodboardUrls.length === 1 ? '' : 's'} detected.
                    </p>
                  )}
                </TabsContent>

                <TabsContent value="flash" className="mt-3">
                  <div className="rounded-lg border border-dashed border-[var(--color-border)] px-6 py-8 text-center">
                    <p className="text-sm text-[var(--color-stone)]">
                      Flash designs coming soon — Sprint 7.
                    </p>
                  </div>
                </TabsContent>
              </Tabs>
            </div>

            {/* Reference notes */}
            <div className="space-y-1.5">
              <Label htmlFor="reference-notes">Reference notes</Label>
              <Textarea
                id="reference-notes"
                placeholder="Describe the style, colour palette, or any specific references…"
                value={referenceNotes}
                onChange={(e) => setReferenceNotes(e.target.value)}
                rows={3}
                maxLength={2000}
                className="resize-none"
              />
            </div>
          </CardContent>
        </Card>

        {/* ── Submit row ───────────────────────────────────────────────────────── */}
        <div className="flex items-center gap-3">
          {/* Auto-save indicator */}
          <div className="flex items-center gap-1.5 text-xs text-[var(--color-stone)] mr-auto">
            {lastSaved !== null && (
              <>
                <span className="inline-block size-1.5 rounded-full bg-[var(--color-stone)]/40" aria-hidden="true" />
                Draft auto-saved
              </>
            )}
          </div>

          <Button
            type="button"
            variant="ghost"
            onClick={() => router.back()}
            disabled={isPending}
          >
            Cancel
          </Button>

          <Button
            type="button"
            variant="outline"
            onClick={handleSubmitProject}
            disabled={isPending}
          >
            {isPending && <Loader2 className="mr-2 size-4 animate-spin" aria-hidden="true" />}
            Create Project
          </Button>

          <Button
            type="button"
            onClick={handleSubmitCalendar}
            disabled={isPending}
            className="bg-[var(--color-onyx)] text-[var(--color-bone)] hover:bg-[var(--color-onyx)]/90"
          >
            {isPending && <Loader2 className="mr-2 size-4 animate-spin" aria-hidden="true" />}
            Create &amp; book first session →
          </Button>
        </div>
      </form>
    </>
  )
}

